import{c as o,$ as a,Q as r,j as c,g as t,n,o as d,m as s}from"./chunks/framework.Xjf2pjgg.js";const q=JSON.parse('{"title":"YuRelic 玩家玩法","description":"","frontmatter":{"title":"YuRelic 玩家玩法"},"headers":[],"relativePath":"plugins/items/yu-relic/gameplay.md","filePath":"plugins/items/yu-relic/gameplay.md"}'),u={name:"plugins/items/yu-relic/gameplay.md"},p={class:"quick-actions"};function h(y,e,b,m,g,f){const i=a("CopyMarkdownButton"),l=a("CopyLLMButton");return r(),c("div",null,[e[0]||(e[0]=t("h1",{id:"yurelic-玩家玩法",tabindex:"-1"},[n("YuRelic 玩家玩法 "),t("a",{class:"header-anchor",href:"#yurelic-玩家玩法","aria-label":'Permalink to "YuRelic 玩家玩法"'},"​")],-1)),t("div",p,[d(i,{page:""}),d(l,{page:""})]),e[1]||(e[1]=s('<h2 id="一分钟上手" tabindex="-1">一分钟上手 <a class="header-anchor" href="#一分钟上手" aria-label="Permalink to &quot;一分钟上手&quot;">​</a></h2><ol><li>主手拿一件可损耗装备，例如剑、斧、弓、盾、护甲或工具。</li><li>输入 <code>/yurelic open</code> 打开开光 GUI，或 <code>/yurelic open basic|refined|exalted</code> 选择档位。</li><li>开光后使用这件装备战斗、挖掘、承伤或完成服务器配置的目标来获得灵器经验。</li><li>用 <code>/yurelic info</code> 或 <code>/yurelic gui</code> 查看等级、经验、器魂、灵契、路线、器体状态。</li><li>到达突破点后输入 <code>/yurelic breakthrough</code> 查看候选路线，再用 <code>/yurelic breakthrough 1</code> 等命令选择。</li><li>器体损耗过高时用 <code>/yurelic repair</code> 或 <code>/yurelic repair resource &lt;灵材&gt;</code> 修复。</li></ol><h2 id="核心循环" tabindex="-1">核心循环 <a class="header-anchor" href="#核心循环" aria-label="Permalink to &quot;核心循环&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开光物品</span></span>\n<span class="line"><span>  -&gt; 建立灵契与器体</span></span>\n<span class="line"><span>  -&gt; 通过真实使用获得灵息经验</span></span>\n<span class="line"><span>  -&gt; 等级提升并积累命痕</span></span>\n<span class="line"><span>  -&gt; 突破选择成长路线</span></span>\n<span class="line"><span>  -&gt; 注魂、铭魂、淬炼、觉醒</span></span>\n<span class="line"><span>  -&gt; 器藏收录、天榜展示、传承或封存</span></span></code></pre></div><p>YuRelic 默认不把装备改成普通数值面板，而是把成长信息写入灵器数据与 Lore。服务器可以通过 GUI 和 PlaceholderAPI 把这些信息显示到菜单、面板、排行榜或聊天分享里。</p><h2 id="开光与器体" tabindex="-1">开光与器体 <a class="header-anchor" href="#开光与器体" aria-label="Permalink to &quot;开光与器体&quot;">​</a></h2><p>开光会读取主手物品类型、名称、Lore、现代 key、NBT 指纹和耐久信息。默认要求物品能读取最大耐久；无耐久模组物品需要服主加入 <code>rpg.non-durable-relics.whitelist</code>。</p><p>开光档位常见含义：</p><table tabindex="0"><thead><tr><th>档位</th><th>用途</th></tr></thead><tbody><tr><td><code>basic</code></td><td>基础开光，适合玩家日常装备</td></tr><tr><td><code>refined</code></td><td>精炼开光，成本更高，品质权重更好</td></tr><tr><td><code>exalted</code></td><td>高阶开光，通常接 Vault、PlayerPoints 或灵材消耗</td></tr></tbody></table><p>器体是灵器自己的寿命概念。原版铁砧修复不等于恢复器体；半损毁后需要 YuRelic 修复体系处理。</p><h2 id="灵契、同调与器忆" tabindex="-1">灵契、同调与器忆 <a class="header-anchor" href="#灵契、同调与器忆" aria-label="Permalink to &quot;灵契、同调与器忆&quot;">​</a></h2><p>开光者默认成为初代器主。只有当前器主长期使用灵器时，灵器才稳定回应并成长。其他玩家持有时可能进入成长沉默。</p><p>常用命令：</p><ul><li><code>/yurelic pact info</code>：查看器主、初照、契序与涤契成本。</li><li><code>/yurelic pact rebind</code>：涤契归心，让灵器重新认主。</li><li><code>/yurelic affinity info</code>：查看同调等级。</li><li><code>/yurelic affinity meditate [注入量]</code>：通过配置的成本通道提高同调。</li><li><code>/yurelic affinity memory</code>：查看器忆文本。</li></ul><h2 id="成长、突破与道韵" tabindex="-1">成长、突破与道韵 <a class="header-anchor" href="#成长、突破与道韵" aria-label="Permalink to &quot;成长、突破与道韵&quot;">​</a></h2><p>灵器经验来自战斗、击杀、采掘、承伤、远程、格挡、经验吸收等行为，具体倍率由服主配置。插件会考虑耐久门禁、反刷、灵息疲劳、LevelledMobs 等级、场景规则和世界倍率。</p><p>到达突破等级后，灵器会生成候选路线。路线会影响后续攻击、防御、成长、修复、控制或辅助倾向。长期按某条路线使用灵器，还会沉淀道韵精通：</p><ul><li><code>/yurelic breakthrough</code>：查看或选择突破路线。</li><li><code>/yurelic mastery</code>：查看道韵精通。</li><li><code>/yurelic combat</code>：查看当前战斗乘区与 PVP/PVE 压缩。</li></ul><h2 id="器魂、潜质、天赋与觉醒" tabindex="-1">器魂、潜质、天赋与觉醒 <a class="header-anchor" href="#器魂、潜质、天赋与觉醒" aria-label="Permalink to &quot;器魂、潜质、天赋与觉醒&quot;">​</a></h2><p>灵器拥有器魂、潜质、六维命痕、天赋和觉醒状态。服主可以通过成本配置控制这些系统的节奏。</p><table tabindex="0"><thead><tr><th>系统</th><th>命令</th><th>作用</th></tr></thead><tbody><tr><td>器魂</td><td>`/yurelic soul info</td><td>feed</td></tr><tr><td>潜质</td><td>`/yurelic potential info</td><td>upgrade`</td></tr><tr><td>天赋</td><td>`/yurelic talent list</td><td>prepare</td></tr><tr><td>觉醒</td><td>`/yurelic awaken info</td><td>start`</td></tr><tr><td>器魂共鸣</td><td>自动触发</td><td>高魂级后获得专属战斗或成长效果</td></tr></tbody></table><h2 id="资源、仪式与灵材" tabindex="-1">资源、仪式与灵材 <a class="header-anchor" href="#资源、仪式与灵材" aria-label="Permalink to &quot;资源、仪式与灵材&quot;">​</a></h2><p>灵材来自掉落、里程碑、活动、商城或管理员发放。常见灵材包括潜质精华、换魂玉、洗练石、觉醒核心、玄刻尘、修灵晶等。</p><ul><li><code>/yurelic resource</code>：查看背包中的 YuRelic 资源。</li><li><code>/yurelic repair resource &lt;灵材&gt; [数量|all]</code>：投入灵材修复。</li><li><code>/yurelic shop</code>：打开灵物坊，使用配置货币购买灵材。</li><li><code>/yurelic loot</code>：查看掉落生态状态。</li></ul><h2 id="饰品、套装与构筑" tabindex="-1">饰品、套装与构筑 <a class="header-anchor" href="#饰品、套装与构筑" aria-label="Permalink to &quot;饰品、套装与构筑&quot;">​</a></h2><p>YuRelic 支持虚拟饰品槽，默认有灵佩、魂坠、戒印、符令四类槽位。饰品槽可以通过权限、等级或材料解锁。</p><ul><li><code>/yurelic accessory list</code>：查看槽位。</li><li><code>/yurelic accessory equip [槽位]</code>：将主手饰品灵器佩戴到虚拟槽。</li><li><code>/yurelic accessory unequip [槽位]</code>：卸下。</li><li><code>/yurelic accessory unlock [槽位]</code>：按配置消耗解锁。</li><li><code>/yurelic sets</code>：查看套装共鸣。</li></ul><h2 id="展示、保护与流转" tabindex="-1">展示、保护与流转 <a class="header-anchor" href="#展示、保护与流转" aria-label="Permalink to &quot;展示、保护与流转&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>命令</th></tr></thead><tbody><tr><td>聊天展示主手灵器</td><td><code>/yurelic share</code></td></tr><tr><td>收录到器藏</td><td><code>/yurelic archive scan</code></td></tr><tr><td>查看器藏</td><td><code>/yurelic archive gui</code></td></tr><tr><td>查看天榜</td><td><code>/yurelic rank gui</code></td></tr><tr><td>鉴定主手灵器</td><td><code>/yurelic appraise</code></td></tr><tr><td>防误丢、防误归炉</td><td><code>/yurelic guard lock</code></td></tr><tr><td>封存可交易灵器</td><td><code>/yurelic seal on</code></td></tr><tr><td>承薪传承旧器</td><td><code>/yurelic heritage absorb</code></td></tr><tr><td>估价与流转记录</td><td>`/yurelic market quote</td></tr></tbody></table><h2 id="gui-入口" tabindex="-1">GUI 入口 <a class="header-anchor" href="#gui-入口" aria-label="Permalink to &quot;GUI 入口&quot;">​</a></h2><p>输入 <code>/yurelic</code> 或 <code>/yurelic gui</code> 通常会打开主菜单。常见页面包括开光、养成、修复、饰品、器藏、天榜、灵物坊、运维、掉落模拟等。GUI 按钮仍调用底层命令，因此权限和配置逻辑保持一致。</p>',31))])}const _=o(u,[["render",h]]);export{q as __pageData,_ as default};
